import json
def components(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] and not seen[r][c]:
                col=g[r][c]; stack=[(r,c)]; seen[r][c]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; stack.append((ny,nx))
                comps.append((col,cells))
    return comps
def norm(cells):
    ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
    my,mx=min(ys),min(xs)
    return frozenset((y-my,x-mx) for y,x in cells)
def transform(g):
    g=[row[:] for row in row if False] if False else [r[:] for r in g]
    comps=components(g)
    sigs={}
    for col,cells in comps: sigs.setdefault(norm(cells),[]).append(col)
    for col,cells in comps:
        if col==1:
            s=norm(cells)
            others=[c for c in sigs.get(s,[]) if c!=1]
            if others:
                tgt=others[0]
                for y,x in cells: g[y][x]=tgt
    return g
